def compute(vars):
    total_shares = vars["v1"] + vars["v2"]
    return {
        "value": total_shares,
        "trace": {
            "shares_november": vars["v1"],
            "shares_december": vars["v2"],
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "shares"
            }
        }
    }
